const http=require('http'),fs=require('fs'),path=require('path'),crypto=require('crypto');
const rooms=new Map(), ranks=['6','7','8','9','10','В','Д','К','Т'], suits=['♠','♥','♣','♦'];
const fail=m=>{throw Error(m)}; const next=i=>(i+1)%4; const team=i=>i%2; const rank=c=>c.slice(0,-1); const suit=c=>c.slice(-1); const eligible=(r,c)=>r.level===9?c==='Д♠':rank(c)===ranks[r.level];
function start(r){r.deck=suits.flatMap(s=>ranks.map(v=>v+s));for(let i=r.deck.length-1;i>0;i--){let j=crypto.randomInt(i+1);[r.deck[i],r.deck[j]]=[r.deck[j],r.deck[i]]}r.trumpCard=r.deck[0];r.trump=suit(r.trumpCard);r.hands=r.players.map(()=>Array.from({length:6},()=>r.deck.pop()));r.table=[];r.pogony=null;r.botAt=Date.now()+1100;r.discard=[];r.passes=[];r.taking=false;r.result=null;r.last=null;r.attack=0;let best=99;r.hands.forEach((h,i)=>h.forEach(c=>{if(suit(c)===r.trump&&ranks.indexOf(rank(c))<best){best=ranks.indexOf(rank(c));r.attack=i}}));r.defend=next(r.attack);r.level=r.levels[team(r.attack)];r.limit=6;r.phase='play';r.deadline=Date.now()+45000;}
function beats(a,b,t){return suit(a)===suit(b)?ranks.indexOf(rank(a))>ranks.indexOf(rank(b)):suit(a)===t&&suit(b)!==t}
function active(r,i){return r.hands[i].length>0}function findNext(r,i,filter=()=>true){for(let k=1;k<=4;k++){let j=(i+k)%4;if(active(r,j)&&filter(j))return j}return -1}
function finish(r){if(r.deck.length)return false;for(let t=0;t<2;t++)if(r.hands.every((h,i)=>team(i)!==t||!h.length)){let other=r.hands.some((h,i)=>team(i)!==t&&h.length);r.phase='end';r.result=other?`Команда ${t+1} победила`:'Ничья';if(other)r.wins[t]++;return true}return false}
function settle(r){let a=r.attack,d=r.defend,t=r.taking;let cards=r.table.flatMap(p=>p.b?[p.a,p.b]:[p.a]);if(t)r.hands[d].push(...cards);else r.discard.push(...cards);r.last=t?{defender:d,attackers:r.table.map(p=>p.by),unbeaten:r.table.filter(p=>!p.b).map(p=>p.a)}:null;for(let k=0;k<4;k++){let i=(a+k)%4;while(r.hands[i].length<6&&r.deck.length)r.hands[i].push(r.deck.pop())}r.table=[];r.passes=[];r.taking=false;if(finish(r))return;let na,nd;if(!t){na=active(r,d)?d:(d+2)%4;nd=findNext(r,d,j=>team(j)!==team(d));if(!active(r,na))na=-1}else{na=findNext(r,d,j=>team(j)!==team(d));nd=na<0?-1:findNext(r,na,j=>team(j)!==team(na))}if(na<0){finish(r);return}r.attack=na;r.defend=nd;r.level=r.levels[team(na)];if(r.defend<0){finish(r);return}r.limit=Math.min(6,r.hands[r.defend].length)}
function fillBots(r,mode){if(r.phase!=='lobby'||r.players.length>4)fail('Комната уже играет');let humans=r.players.slice();let names=['Бот Шахтёр','Бот Горняк','Бот Мастер'];let bot=()=>({name:names.shift()||'Бот',bot:true,token:crypto.randomBytes(24).toString('hex')});if(humans.length===2&&mode==='together')r.players=[humans[0],bot(),humans[1],bot()];else while(r.players.length<4)r.players.push(bot());start(r)}
function action(r,i,b){if(b.type==='fill'){if(i!==0)fail('Только создатель комнаты');fillBots(r,b.mode);return}if(b.type==='start'){if(i!==0||r.players.length!==4||r.phase==='play')fail('Нужно четыре игрока и завершённая партия');start(r);return}if(r.phase!=='play')fail('Партия не начата');let h=r.hands[i],c=b.card;let attackers=[r.attack,(r.attack+2)%4];let canAttack=attackers.includes(i)&&team(i)!==team(r.defend);let remove=()=>{let k=h.indexOf(c);if(k<0)fail('Карты нет на руках');h.splice(k,1)};
if(b.type==='attack'){if(!canAttack||r.passes.includes(i)||(!r.table.length&&i!==r.attack))fail('Не ваш ход');if(r.table.length>=r.limit)fail('Лимит карт');if(r.table.length&&!r.table.some(p=>rank(p.a)===rank(c)||(p.b&&rank(p.b)===rank(c))))fail('Нет такого достоинства на столе');remove();r.table.push({a:c,b:null,by:i});r.passes=[];return}
if(b.type==='beat'){if(i!==r.defend||r.taking)fail('Вы не отбиваетесь');let p=r.table[b.index];if(!p||p.b||!h.includes(c)||!beats(c,p.a,r.trump))fail('Карта не бьёт');remove();p.b=c;r.passes=[];return}
if(b.type==='take'){if(i!==r.defend||!r.table.some(p=>!p.b)||r.taking)fail('Нельзя взять');r.taking=true;r.passes=[];return}
if(b.type==='pogony'){if(!canAttack||!h.length||!h.every(c=>eligible(r,c))||r.deck.length||!r.taking||!r.table.length||!r.table.some(p=>!p.b))fail('Погоны только после принятия неотбитой атаки, без колоды');let a=r.hands[r.attack],p=r.hands[(r.attack+2)%4],all=[...a,...p],min=r.level===9?1:2;if(!all.length||!all.every(c=>eligible(r,c))||all.length<min)fail('Погоны сейчас невозможны');let t=team(i);r.pogony={cards:all,team:t,target:r.defend,level:r.level};r.hands[r.defend].push(...r.table.flatMap(p=>p.b?[p.a,p.b]:[p.a]),...all);a.length=0;p.length=0;r.table=[];r.wins[t]++;r.medals[t]++;r.hanging[t]=r.level===9?'Д♠':ranks[r.level];r.result=`Команда ${t+1}: погоны ${all.join(' ')}`;r.level=Math.min(9,r.level+1);if(r.pogony.level===9){r.level=0;r.champions[t]++}r.levels[t]=r.level;r.phase='end';return}
if(b.type==='pass'){if(!canAttack||!r.table.length||(!r.taking&&r.table.some(p=>!p.b)))fail('Сначала противник должен отбиться или взять');if(!r.passes.includes(i))r.passes.push(i);if(attackers.every(j=>!active(r,j)||r.passes.includes(j)))settle(r);return}fail('Неизвестное действие')}
function botStep(r){if(r.phase!=='play')return;let now=Date.now();if(now<(r.botAt||0))return;let a=r.attack,d=r.defend,attackers=[a,(a+2)%4],isBot=i=>r.players[i]?.bot,sorted=h=>h.slice().sort((x,y)=>(suit(x)===r.trump?20:0)+ranks.indexOf(rank(x))-(suit(y)===r.trump?20:0)-ranks.indexOf(rank(y)));let move=null;
if(!r.table.length){if(isBot(a)&&active(r,a))move=[a,{type:'attack',card:sorted(r.hands[a])[0]}]}
else if(!r.taking&&r.table.some(p=>!p.b)){if(isBot(d)){let index=r.table.findIndex(p=>!p.b),c=sorted(r.hands[d]).find(c=>beats(c,r.table[index].a,r.trump));move=[d,c?{type:'beat',card:c,index}:{type:'take'}]}}
else {if(attackers.some(i=>!isBot(i)&&active(r,i)&&!r.passes.includes(i))&&now<r.deadline-40000)return;for(let i of attackers){if(!isBot(i)||r.passes.includes(i)||!active(r,i))continue;let h=r.hands[i];if(r.taking&&!r.deck.length&&h.every(c=>eligible(r,c))){try{action(r,i,{type:'pogony'});r.botAt=now+1000;r.deadline=now+45000;return}catch(e){}}let c=r.table.length<r.limit&&sorted(h).find(c=>r.table.some(p=>rank(p.a)===rank(c)||(p.b&&rank(p.b)===rank(c))));move=[i,c?{type:'attack',card:c}:{type:'pass'}];break}if(!move&&attackers.every(i=>!active(r,i)||r.passes.includes(i))){settle(r);r.deadline=now+45000;r.botAt=now+1000;return}}
if(move){try{action(r,...move);r.deadline=now+45000}catch(e){console.error('bot',e.message)}r.botAt=now+1100}}
function tick(r){if(r.phase!=='play')return;let now=Date.now();if(now<r.deadline){botStep(r);return}try{if(!r.table.length){action(r,r.attack,{type:'attack',card:r.hands[r.attack][0]})}else if(!r.taking&&r.table.some(p=>!p.b)){action(r,r.defend,{type:'take'})}else{let attackers=[r.attack,(r.attack+2)%4];for(const j of attackers){if(r.phase!=='play'||!r.table.length)break;if(!r.passes.includes(j))action(r,j,{type:'pass'})}}}catch(e){console.error('timer',e.message)}r.deadline=now+45000;r.botAt=now+1100}setInterval(()=>{for(const r of rooms.values())tick(r)},500).unref();
function view(r,i){return {code:r.code,me:i,players:r.players.map(p=>p.name),bots:r.players.map(p=>!!p.bot),phase:r.phase,hand:r.hands?.[i]||[],counts:r.hands?.map(h=>h.length)||[],deck:r.deck?.length||0,trump:r.trump,trumpCard:r.trumpCard,deadline:r.deadline,now:Date.now(),chat:r.chat||[],table:r.table||[],attack:r.attack,defend:r.defend,taking:r.taking,passes:r.passes||[],level:r.level,target:r.level===9?'Д♠':ranks[r.level],wins:r.wins,medals:r.medals,hanging:r.hanging,champions:r.champions,result:r.result,pogony:r.phase==='end'?r.pogony:null}}
const server=http.createServer(async(req,res)=>{try{let u=new URL(req.url,'http://localhost');if(u.pathname.startsWith('/api/')){let b={};if(req.method==='POST'){let s='';for await(let chunk of req){s+=chunk;if(s.length>16000)fail('Слишком большой запрос')}b=JSON.parse(s||'{}')}let r=rooms.get((b.code||u.searchParams.get('code')||'').toUpperCase()),token=b.token||u.searchParams.get('token');let out;if(u.pathname==='/api/create'){let code;do{code=crypto.randomBytes(3).toString('hex').toUpperCase()}while(rooms.has(code));r={code,players:[],phase:'lobby',chat:[],level:0,levels:[0,0],hanging:['0','0'],wins:[0,0],medals:[0,0],champions:[0,0]};rooms.set(code,r)}if(!r)fail('Комната не найдена');if(['/api/create','/api/join'].includes(u.pathname)){if(r.phase!=='lobby'||r.players.length>=4)fail('Комната закрыта или заполнена');token=crypto.randomBytes(24).toString('hex');r.players.push({name:String(b.name||'Игрок').slice(0,24),token});out={code:r.code,token};if(u.pathname==='/api/create'&&b.solo)fillBots(r,'split')}else{let i=r.players.findIndex(p=>p.token===token);if(i<0)fail('Нет доступа');tick(r);if(u.pathname==='/api/action'){action(r,i,b);r.deadline=Date.now()+45000;r.botAt=Date.now()+1100;if(b.type==='start')r.pogony=null}if(u.pathname==='/api/chat'){let msg=String(b.message||'').trim().slice(0,300);if(!msg)fail('Пустое сообщение');let now=Date.now();if(now-(r.players[i].lastChat||0)<750)fail('Слишком часто');r.players[i].lastChat=now;r.chat.push({id:crypto.randomUUID(),name:r.players[i].name,message:msg});r.chat=r.chat.slice(-60)}out=view(r,i)}res.setHeader('Content-Type','application/json');res.setHeader('Cache-Control','no-store');res.end(JSON.stringify(out));return}let f=u.pathname==='/'?'index.html':u.pathname.slice(1);if(!['index.html','manifest.json'].includes(f)){res.writeHead(404);res.end();return}res.setHeader('Content-Type',f.endsWith('html')?'text/html; charset=utf-8':'application/manifest+json');res.end(Buffer.from(ASSETS[f],'base64'))}catch(e){res.writeHead(400,{'Content-Type':'application/json; charset=utf-8'});res.end(JSON.stringify({error:e.message}))}});server.listen(process.env.PORT||3000,'0.0.0.0');
